const item = $input.item.json;
const payload =
  item.body && typeof item.body === "object"
    ? item.body
    : item;

const requiredFields = [
  "name",
  "email",
  "phone",
  "projectType",
  "budget",
  "location",
  "timeline",
  "description",
];

const errors = [];

for (const field of requiredFields) {
  const value = payload[field];
  if (typeof value !== "string" || !value.trim()) {
    errors.push(`${field} is required`);
  }
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (typeof payload.email !== "string" || !emailRegex.test(payload.email.trim())) {
  errors.push("email must be valid");
}

return [
  {
    json: {
      payload,
      isValid: errors.length === 0,
      validationErrors: errors,
    },
  },
];

const item = $input.item.json;

if (item.isValid !== true) {
  throw new Error('Invalid payload cannot be prepared for DB insert.');
}

const lead = item.payload;

return [
  {
    json: {
      leadRecord: {
        name: lead.name.trim(),
        email: lead.email.trim().toLowerCase(),
        phone: lead.phone.trim(),
        project_type: lead.projectType.trim(),
        budget: lead.budget.trim(),
        location: lead.location.trim(),
        timeline: lead.timeline.trim(),
        description: lead.description.trim(),
        source: "form",
        created_at: new Date().toISOString(),
      },
    },
  },
];

// Prepare prompt for Gemini API
const item = $input.item.json;
const lead = item.leadRecord;

const systemPrompt = `You are a lead qualification assistant for a home renovation company.

Analyze the lead data and return ONLY valid JSON matching this exact schema:
{
  "leadScore": number (0-100),
  "classification": "HOT" | "WARM" | "COLD",
  "estimatedValue": number,
  "urgency": "LOW" | "MEDIUM" | "HIGH",
  "summary": "1-2 sentence summary",
  "recommendedAction": "short action string"
}

Scoring guidance:
- Higher budgets increase score (Budget $50k+ should score 35-40 points)
- Urgent timelines increase score (ASAP/Within 1 month should score 25-30 points)
- Detailed project descriptions increase score (100+ chars should score 25-30 points)
- HOT classification: score >= 70
- WARM classification: score 40-69
- COLD classification: score < 40

Recommended actions:
- HOT: "Contact within 24 hours - high priority"
- WARM: "Follow up within 2-3 days"
- COLD: "Add to nurture campaign"

Lead data:
Project Type: ${lead.project_type}
Budget: ${lead.budget}
Timeline: ${lead.timeline}
Location: ${lead.location}
Description: ${lead.description}
Name: ${lead.name}`;

return [
  {
    json: {
      leadRecord: lead,
      geminiPrompt: systemPrompt,
    },
  },
];

// Parse Gemini response and handle errors
const item = $input.item.json;
const lead = $node["Prepare AI Prompt"].json.leadRecord;

let aiQualification;

try {
  const statusCode = item.statusCode || 200;

  if (statusCode >= 200 && statusCode < 300 && item.body) {
    const body = typeof item.body === 'string' ? JSON.parse(item.body) : item.body;

    // Extract text from Gemini response structure
    const responseText = body?.candidates?.[0]?.content?.parts?.[0]?.text;

    if (!responseText) {
      throw new Error('No text in Gemini response');
    }

    // Parse the JSON response from Gemini
    const aiResult = JSON.parse(responseText);

    // Validate required fields
    if (!aiResult.leadScore || !aiResult.classification) {
      throw new Error('Invalid AI response structure');
    }

    aiQualification = {
      lead_score: aiResult.leadScore,
      classification: aiResult.classification,
      estimated_value: aiResult.estimatedValue || 0,
      urgency: aiResult.urgency || 'LOW',
      ai_summary: aiResult.summary || 'AI-scored lead',
      recommended_action: aiResult.recommendedAction || 'Review manually',
      ai_scored_at: new Date().toISOString(),
    };
  } else {
    throw new Error(`Gemini API error: ${statusCode}`);
  }
} catch (error) {
  // Fallback to UNSCORED if AI fails
  console.error('AI scoring failed:', error.message);

  aiQualification = {
    lead_score: null,
    classification: 'UNSCORED',
    estimated_value: null,
    urgency: null,
    ai_summary: `AI scoring failed: ${error.message}`,
    recommended_action: 'Manual review required - AI unavailable',
    ai_scored_at: new Date().toISOString(),
  };
}

return [
  {
    json: {
      leadRecord: lead,
      aiQualification: aiQualification,
    },
  },
];

// Merge lead data with AI qualification results
const item = $input.item.json;
const lead = item.leadRecord;
const ai = item.aiQualification;

// Combine into final database record
const finalRecord = {
  ...lead,
  ...ai,
};

return [
  {
    json: {
      finalRecord: finalRecord,
    },
  },
];

const item = $input.item.json;
const statusCode = item.statusCode || item.status || 200;
const body = item.body ?? item;

if (statusCode >= 200 && statusCode < 300) {
  return [
    {
      json: {
        statusCode: 200,
        response: {
          ok: true,
          message: "Lead payload accepted and saved",
          record: body,
        },
      },
    },
  ];
}

return [
  {
    json: {
      statusCode: 500,
      response: {
        ok: false,
        message: "Database write failed",
        details: body,
      },
    },
  },
];

const item = $input.item.json;

return [
  {
    json: {
      statusCode: 400,
      response: {
        ok: false,
        message: "Payload validation failed",
        errors: item.validationErrors,
      },
    },
  },
];
